const question = $json.body?.question;

if (!question || !question.trim()) {
  throw new Error('Send a JSON body with a "question" field.');
}

return [
  {
    json: {
      question: question.trim(),
      inputs: [question.trim()],
    },
  },
];

const question = $('Prepare User Question').first().json.question;
const vector = $input.first().json.data?.[0]?.embedding;

if (!vector) {
  throw new Error('Nebius did not return an embedding for the question.');
}

const q = question.toLowerCase();
const matchedSources = new Set();

// HR-related questions
if (/\b(pto|paid time off|leave|benefit|full-time|remote work|contractor|equipment|parental|sick day|holiday)\b/.test(q)) {
  matchedSources.add('HR Policy');
}

// Compliance-related questions
if (/\b(compliance|violation|ethics|report|whistleblower|retaliation)\b/.test(q)) {
  matchedSources.add('Compliance Manual');
}

// Onboarding-related questions
if (/\b(onboarding|orientation|first day|new employee)\b/.test(q)) {
  matchedSources.add('Onboarding Guide');
}

// Technical/API-related questions
if (/\b(api|oauth|token|gateway|kong|authentication|endpoint)\b/.test(q)) {
  matchedSources.add('Technical Documentation');
}

// Filter only when the question matches exactly one document area.
// Broad or cross-document questions search the whole knowledge base.
const pineconeFilter =
  matchedSources.size === 1
    ? { source: { $eq: [...matchedSources][0] } }
    : undefined;

return [
  {
    json: {
      question,
      vector,
      topK: 8,
      includeMetadata: true,
      namespace: 'acme-policies',
      pineconeFilter,
    },
  },
];

const question = $('Prepare Pinecone Search').first().json.question;
const matches = $input.first().json.matches ?? [];

// Start conservatively. We can tune this after testing.
const MIN_SIMILARITY_SCORE = 0.35;
const MAX_CONTEXT_CHUNKS = 4;

// Pinecone may already return ordered results, but sort explicitly so the
// workflow always uses the strongest chunks first.
const rankedMatches = matches
  .filter((match) => typeof match.score === 'number')
  .sort((a, b) => b.score - a.score);

// Remove weak matches, then use only the best four chunks as LLM context.
const selectedMatches = rankedMatches
  .filter((match) => match.score >= MIN_SIMILARITY_SCORE)
  .slice(0, MAX_CONTEXT_CHUNKS);

const context = selectedMatches
  .map((match, index) => {
    const metadata = match.metadata ?? {};
    return [
      `RESULT ${index + 1}`,
      `Source: ${metadata.source ?? 'Unknown'}`,
      `URL: ${metadata.url ?? 'Unknown'}`,
      `Similarity score: ${match.score.toFixed(3)}`,
      '',
      metadata.text ?? '',
    ].join('\n');
  })
  .join('\n\n---\n\n');

const sources = [
  ...new Set(
    selectedMatches
      .map((match) => match.metadata?.source)
      .filter(Boolean)
  ),
];

return [
  {
    json: {
      question,
      context: context || 'No relevant policy context was retrieved.',
      sourceCount: selectedMatches.length,
      sources,
      retrieval: {
        retrieved: matches.length,
        selected: selectedMatches.length,
        threshold: MIN_SIMILARITY_SCORE,
      },
    },
  },
];

